var yc;
var n;
var rot;
var off;
var rh;
var speed;

function setup() {
  createCanvas(windowWidth, windowHeight); 
  background(100);  
  rectMode(CENTER);

  yc = windowHeight / 2;
  n = 121;
  off = 0;
} 

function draw() {
  background(40);
  stroke(255);
  noFill();

  n = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, windowWidth, 20, 250);
  rh = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, windowHeight, 10, 800);

  for(var i = 0; i < n; i++){
    push();
	translate((windowWidth / n) * i, yc);
    rot = ((TWO_PI / n) * i) + off;
    rot = sin(rot);
    rotate(rot);
  	rect(0, 0, 50, rh);
    translate(-((windowWidth / n) * i), -yc);
  	pop();
  }

  speed = map(n, 20, 250, 0.3, 1.2);
  off += (TWO_PI / n) * speed;
}
